/// <summary>
/// handle buttons related to sales order form
/// </summary>
[ExtensionOf(classStr(SalesTableInteraction))]
Public final class METSalesTableInteraction_Extension
{
    
    #localmacro.SetEnabled
        macroFormControlStr = %1;
        if (page.actionPaneControlVisible(macroFormControlStr))
        {
            page.actionPaneControlEnabled(macroFormControlStr, %2);
        }
    #endmacro
}

Method.Source:
    /// </summary>
    /// MPJ_24819_SOParametersAndCancelLinePickList
    /// Control “Remove”, “Add Line”, ”Add Products” and “Add Lines” buttons
    /// </summary>
    protected void enableLineFunctionActions()
    {
        next enableLineFunctionActions();

        if(METCustParameters::find().DisableSOLineEdit)
        {
            SalesLine       metSalesLineStd;
            METSalesLine    metSalesLine;

            select firstonly OrderExtractStatus from metSalesLine
                exists join metSalesLineStd
                where metSalesLineStd.RecId == metSalesLine.SalesLine &&
                metSalesLineStd.SalesId              == salesTable.SalesId &&
                metSalesLine.OrderExtractStatus    == METOrderExtractStatus::Extracted;
            if(metSalesLine.OrderExtractStatus)
            {
                #SetEnabled(formcontrolstr(SalesTable, LineStripNew),  false);
                #SetEnabled(formcontrolstr(SalesTable, ButtonLineQuickQuote),  false);
                #SetEnabled(formcontrolstr(SalesTable, RetailAddItemMenuItem),  false);
                #SetEnabled(formcontrolstr(SalesTable, LineStripDelete),  false);
                #SetEnabled(formcontrolstr(SalesTable, SalesUpdateRemain),  false);
                
            }
            else
            {
                #SetEnabled(formcontrolstr(SalesTable, LineStripNew),  true);
                #SetEnabled(formcontrolstr(SalesTable, ButtonLineQuickQuote),  true);
                #SetEnabled(formcontrolstr(SalesTable, RetailAddItemMenuItem),  true);
                #SetEnabled(formcontrolstr(SalesTable, LineStripDelete),  true);
                #SetEnabled(formcontrolstr(SalesTable, SalesUpdateRemain),  true);
               
            }
        }
        
    }

    /// </summary>
    /// MPJ_24819_SOParametersAndCancelLinePickList
    /// Control “Update Line > Delivery Remainder” button
    /// </summary>
    protected void enableLineRetailActions()
    {
        next enableLineRetailActions();
        if(METCustParameters::find().DisableSOLineEdit)
        {
            SalesLine       metSalesLineStd;
            METSalesLine    metSalesLine;

            select firstonly OrderExtractStatus from metSalesLine
                exists join metSalesLineStd
                where metSalesLineStd.RecId == metSalesLine.SalesLine &&
                metSalesLineStd.SalesId              == salesTable.SalesId &&
                metSalesLine.OrderExtractStatus    == METOrderExtractStatus::Extracted;
            if(metSalesLine.OrderExtractStatus)
            {
        
                #SetEnabled(formcontrolstr(SalesTable, retailAddItemMenuItem), false)
            }
            else
            {
                #SetEnabled(formcontrolstr(SalesTable, retailAddItemMenuItem), true)
            }
        }       

    }
